import React from "react";

function Dashboard() {

  return (
    <div>

      <h1>LMS Dashboard</h1>

      <h3>Welcome to Learning Management System</h3>

      <ul>
        <li>My Courses</li>
        <li>Assignments</li>
        <li>Progress</li>
        <li>Profile</li>
      </ul>

    </div>
  );
}

export default Dashboard;
